function HeroSelectionViewModel:InitProperties()
    self.bIsMainUIOpened = self:createProperty(false)
    self.SelectedHeroID = self:createProperty(HeroSelectionManager:GetSelectedHeroID(UGCGameSystem.GetLocalPlayerKey()))
    self.FocusedHeroID = self:createProperty(HeroSelectionManager:GetCurrentFocusedHeroID())
